import{_ as e,o as t,c as o,a6 as r}from"./chunks/framework.CswKMrA6.js";const b=JSON.parse('{"title":"Building a Dashboard","description":"Five routes to an LCARS dashboard with LCARdS: generate one from your areas, add LCARS sections to a sections dashboard, design one with Claude and the LCARdS skill, borrow a layout from a sample screen, or build it by hand on a layout view.","frontmatter":{"description":"Five routes to an LCARS dashboard with LCARdS: generate one from your areas, add LCARS sections to a sections dashboard, design one with Claude and the LCARdS skill, borrow a layout from a sample screen, or build it by hand on a layout view."},"headers":[],"relativePath":"getting-started/building-dashboards.md","filePath":"getting-started/building-dashboards.md","lastUpdated":1794874007000}'),s={name:"getting-started/building-dashboards.md"};function i(d,a,n,h,l,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="building-a-dashboard" tabindex="-1">Building a Dashboard <a class="header-anchor" href="#building-a-dashboard" aria-label="Permalink to &quot;Building a Dashboard&quot;">​</a></h1><p><strong>There are five routes to an LCARS dashboard, from a screen LCARdS builds in a minute to one you lay out card by card.</strong> Start with the quickest that fits: anything LCARdS generates can be taken over and edited later.</p><table tabindex="0"><thead><tr><th>Route</th><th>What you get</th><th>Where</th></tr></thead><tbody><tr><td><a href="#generate-a-dashboard">Generate a dashboard</a></td><td>A whole LCARS screen for your rooms that keeps itself up to date</td><td><a href="./dashboard-strategies.html">Dashboard Strategies</a></td></tr><tr><td><a href="#add-lcars-sections">Add LCARS sections</a></td><td>Readings, gauges and controls for an area, on any sections dashboard</td><td><a href="./section-strategies.html">Section Strategies</a></td></tr><tr><td><a href="#design-it-with-ai">Design it with AI</a></td><td>A screen planned with you for your own entities, YAML checked before you paste it</td><td><a href="./ai-assistance.html">Getting AI Help</a></td></tr><tr><td><a href="#borrow-a-layout">Borrow a layout</a></td><td>A finished sample screen to copy from</td><td><a href="./dashboard-gallery.html">Dashboard Gallery</a></td></tr><tr><td><a href="#build-it-by-hand">Build it by hand</a></td><td>Every card chosen and placed yourself</td><td><a href="./build-by-hand.html">Build by Hand</a>, then <a href="./bring-it-to-life.html">Bring It to Life</a></td></tr></tbody></table><h2 id="generate-a-dashboard" tabindex="-1">Generate a dashboard <a class="header-anchor" href="#generate-a-dashboard" aria-label="Permalink to &quot;Generate a dashboard&quot;">​</a></h2><p><strong>A dashboard strategy draws a whole LCARS screen from a few settings: pick LCARS Dashboard in Home Assistant&#39;s Add dashboard dialog and it fills itself.</strong> See <a href="./dashboard-strategies.html">Dashboard Strategies</a>.</p><ul><li>It rebuilds itself as you add, rename or move areas, devices and entities, so it never goes stale.</li><li>To change its cards, take control: Home Assistant keeps what the strategy made as an ordinary dashboard you can edit.</li></ul><h2 id="add-lcars-sections" tabindex="-1">Add LCARS sections <a class="header-anchor" href="#add-lcars-sections" aria-label="Permalink to &quot;Add LCARS sections&quot;">​</a></h2><p><strong>Section strategies add LCARS building blocks to Home Assistant&#39;s sections dashboards: readings, gauges and controls for an area, in the classic or Picard look.</strong> See <a href="./section-strategies.html">Section Strategies</a>.</p><ul><li>They sit beside your own sections and Home Assistant&#39;s, so you can try LCARdS on a dashboard you already have.</li><li>Each section rebuilds itself for its area; take control of one to edit its cards.</li></ul><h2 id="design-it-with-ai" tabindex="-1">Design it with AI <a class="header-anchor" href="#design-it-with-ai" aria-label="Permalink to &quot;Design it with AI&quot;">​</a></h2><p><strong>Claude with the LCARdS skill plans a dashboard with you and writes the YAML: describe the screen you want, pick from the concepts it shows, and it checks the result before you paste it.</strong> See <a href="./ai-assistance.html">Getting AI Help</a>.</p><ul><li>In Claude Code, <code>/lcards:dashboard</code> runs the whole conversation: a few questions, two or three concepts with a layout sketch each, then the YAML.</li><li>It uses your real entity ids: tell it them, or connect it to Home Assistant with <a href="./ai-assistance.html#give-claude-your-home-s-context-ha-mcp">ha-mcp</a>.</li></ul><h2 id="borrow-a-layout" tabindex="-1">Borrow a layout <a class="header-anchor" href="#borrow-a-layout" aria-label="Permalink to &quot;Borrow a layout&quot;">​</a></h2><p><strong>The <a href="./dashboard-gallery.html">Dashboard Gallery</a> has sample screens, each a whole view with its YAML and a recording.</strong> Copy a layout or a part of one, then point it at your own entities.</p><ul><li>The samples use test helpers and hand-picked colours: read the gallery&#39;s note on colours before you copy one.</li></ul><h2 id="build-it-by-hand" tabindex="-1">Build it by hand <a class="header-anchor" href="#build-it-by-hand" aria-label="Permalink to &quot;Build it by hand&quot;">​</a></h2><p><strong>For a screen that is exactly yours, pick a card for each job and lay them out on a layout view.</strong> <a href="./build-by-hand.html">Build by Hand</a> walks through it: which card does what, and how to lay out the grid.</p><ul><li><a href="./bring-it-to-life.html">Bring It to Life</a> then shows a screen reacting: a colour that changes at a threshold, a smoothed live reading with its history, and a screen that follows alert mode.</li></ul><h2 id="help-along-the-way" tabindex="-1">Help along the way <a class="header-anchor" href="#help-along-the-way" aria-label="Permalink to &quot;Help along the way&quot;">​</a></h2><p><strong>The design guide, the AI skill and the config checker help on every route.</strong></p><ul><li><a href="./lcars-design.html">Designing LCARS Screens</a> covers the look: colour roles, frames, screen shapes and ready-made patterns.</li><li>Claude with the <a href="./ai-assistance.html">LCARdS skill</a> helps on any route too: a card for one job, a fix for YAML that misbehaves, a section of a screen.</li><li><a href="./config-checker.html">Check Your Config</a> shows invalid keys and values in any LCARdS YAML.</li></ul>',21)])])}const g=e(s,[["render",i]]);export{b as __pageData,g as default};
